mapper.select:
SELECT FROM sku WHERE deleted_at IS NULL
AND id IN #{id}
AND 1 = 0

SELECT  FROM sku WHERE spu_id = #{spuId} AND tenant_id = #{tenantId}
AND deleted_at IS NOT NULL AND deletion_kind = 'P'AND deleted_at IS NULL
ORDER BY id

mapper.delete:
DELETE FROM sku WHERE spu_id = #{spuId} AND tenant_id = #{tenantId}
AND EXISTS (SELECT 1 FROM spu parent WHERE parent.id = #{spuId} AND parent.tenant_id = #{tenantId}
    AND parent.version = #{version} AND parent.deleted_at = #{deletedAt} FOR UPDATE)
